oracleReaderQuery.value:
@concat(
        'SELECT * FROM C##TESTUSER.', item(), 
        ' WHERE Timestamp >= TO_TIMESTAMP(''', pipeline().parameters.WindowStart, ''', ''MM/DD/YY, HH:MI:SS AM'') ',
        'AND Timestamp < TO_TIMESTAMP(''', pipeline().parameters.WindowEnd, ''', ''MM/DD/YY, HH:MI:SS AM'')'
    )
